#!/usr/bin/env bash
# check-review-trail.sh の fixture テスト（Issue #25）。
#
# 【なぜこれが要るか】
#   プロセス検査そのもの（PR コメントを見る部分）はローカルに検査対象が無く
#   make verify には入れられない（verification-loop.md「例外: プロセス検査」）。
#   だが *チェッカのロジック* は TRAIL_FILE / REVIEW_LOOP_DOC を差し替えれば
#   完全にローカル実行できる。ここは「ローカル再現が必須」の側であり、検査する。
#
#   実害があった: 見出しを `###` ちょうどに限定していたため `## 往復 4` /
#   `#### 往復 4` / `###往復 4` が黙殺され、上限超過が OK で通っていた。
#   fixture があれば実装前に出ていた。
#
# 【mawk で走らせること】
#   GitHub runner の既定 awk は mawk で、`#{1,6}` のような ERE の区間指定を
#   解釈せず条件が常に偽になる（gawk では通るため気づかない）。つまり
#   「修正が黙って無効化される」種類のバグが起きうる。見出しレベル違いのケースを
#   ここで固定しておけば、`#+` が将来「読みやすく」`#{1,6}` に書き戻されたときに
#   このテストが落ちる。
set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TARGET="${SCRIPT_DIR}/check-review-trail.sh"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

pass=0
fail=0

# 上限 3 の doc（本番と同じ書式）
cat > "${WORK}/cap3.md" <<'EOF'
| 上限 | 値 | 主語 / 数える対象 |
|---|---|---|
| 同一失敗の再試行 | **3** | AI 単独 |
| 実装↔レビューの往復 | **3** | オーケストレーター↔工程 |
EOF

# 上限 5 の doc（単一情報源を変えたら検査が追随することの確認用）
cat > "${WORK}/cap5.md" <<'EOF'
| 上限 | 値 | 主語 / 数える対象 |
|---|---|---|
| 同一失敗の再試行 | **3** | AI 単独 |
| 実装↔レビューの往復 | **5** | オーケストレーター↔工程 |
EOF

# 上限行が読めない doc（表の書式が動いた状況）。散文に太字数字があっても拾わない。
cat > "${WORK}/nocap.md" <<'EOF'
実装↔レビューの往復は **9** 回くらいが目安、という散文。
EOF

# run_case <名前> <期待rc> <doc> <fixture本文> [期待する出力の部分文字列...]
run_case() {
  local name="$1" want_rc="$2" doc="$3" body="$4"; shift 4
  local trail="${WORK}/trail.txt" out rc ok=1 sub

  printf '%s' "$body" > "$trail"
  out="$(TRAIL_FILE="$trail" REVIEW_LOOP_DOC="${WORK}/${doc}" bash "$TARGET" 2>&1)"
  rc=$?

  [ "$rc" = "$want_rc" ] || ok=0
  for sub in "$@"; do
    grep -qF -- "$sub" <<< "$out" || ok=0
  done

  if [ "$ok" = 1 ]; then
    pass=$((pass + 1))
    printf '  ok   %s (rc=%s)\n' "$name" "$rc"
  else
    fail=$((fail + 1))
    printf '  FAIL %s (rc=%s, 期待 rc=%s)\n' "$name" "$rc" "$want_rc"
    sed 's/^/       | /' <<< "$out"
  fi
}

OK_BLOCK='
###### --- comment 111 ---
### 往復 1
- Critical: 0 — なし
- Warning : 0 — なし
- Info    : 1 — 提案
- 対応    : x
- 未解決  : なし
'

echo "==> test-check-review-trail"

# --- 正常系 -----------------------------------------------------------------
run_case "正常: 必須5行そろい" 0 cap3.md "$OK_BLOCK" "OK: 往復ブロック 1 個"

run_case "正常: 上限ちょうど（3 ≤ 3）" 0 cap3.md '
###### --- c1 ---
### 往復 3
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし
' "最大 往復 3 ≤ 上限 3"

# --- 必須行の欠落 -----------------------------------------------------------
run_case "NG: 必須行が欠けている（未解決なし）" 1 cap3.md '
###### --- c1 ---
### 往復 1
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
' "必須行が欠けている" "未解決"

# --- コメント境界跨ぎ -------------------------------------------------------
# 別コメントの「- 未解決 :」を直前の往復のものとして数えない（検査が甘くならない）。
run_case "NG: コメント境界を跨いだ必須行は数えない" 1 cap3.md '
###### --- c1 ---
### 往復 1
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x

###### --- c2 ---
- 未解決  : なし
' "必須行が欠けている" "未解決"

# --- 章跨ぎ（往復以外の見出しでブロックを閉じる）----------------------------
run_case "NG: 別章の見出しを跨いだ必須行は数えない" 1 cap3.md '
###### --- c1 ---
### 往復 1
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x

## 補足
- 未解決  : なし
' "必須行が欠けている" "未解決"

# --- 上限超過 ---------------------------------------------------------------
run_case "NG: 上限超過（4 > 3）" 1 cap3.md '
###### --- c1 ---
### 往復 4
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし
' "往復 4 が上限 3 を超えている"

# --- 見出しレベル違い（C-1 の回帰テスト。mawk でここが効くこと）--------------
# `###` ちょうどに限定していた頃は、これら3つが汎用見出しルールに吸われて
# 「存在しないもの」になり、上限超過が OK（rc=0）で通っていた。
for h in '## 往復 4' '#### 往復 4' '###往復 4' '#####  往復  4'; do
  run_case "NG: 見出しレベル違いを黙殺しない [${h}]" 1 cap3.md "
###### --- c1 ---
${h}
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし
" "見出しが定型『### 往復 N』でない" "往復 4 が上限 3 を超えている"
done

# --- C-1 の実バグ形（正常ブロック + レベル違い見出しの混在）------------------
# 上のケースはいずれも *ミスレベル見出し単独* のため、C-1 バグを再現しても
# 「ブロックが1つも無い」で rc は 1 のままになり、rc が弁別子にならない
# （アサーション文言を緩めた瞬間、回帰が rc で捕まらなくなる）。
# 正常な `### 往復 1` を併置すると count > 0 になり、`## 往復 4` を黙殺した瞬間
# rc=0（偽の Green）に落ちる。ここが本番で起きていた形そのもの。
run_case "NG: 正常ブロックがあっても別コメントのレベル違い上限超過を見逃さない" 1 cap3.md '
###### --- c1 ---
### 往復 1
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし

###### --- c2 ---
## 往復 4
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし
' "見出しが定型『### 往復 N』でない" "往復 4 が上限 3 を超えている"

# --- 自然な日本語の見出しで誤爆しない（W-1）---------------------------------
# 「往復 N」を含むだけの見出しを往復ブロック扱いにすると、エージェントが日本語で
# 普通に書く見出しで必須チェックが恒久的に赤くなる（復旧はコメント編集のみ）。
# 往復見出しは *数字のあとが区切り文字か行末* のものに限る。上の C-1 ケース群
# （`## 往復 4` 等）が NG のままであることと併せて、「誤爆面だけを狭めた」ことが固定される。
for h in '#### 往復 1 の指摘への回答' '## 往復2回目のレビューまとめ' '### 往復 3 について補足'; do
  run_case "正常: 往復 N を含む自然な見出しで誤爆しない [${h}]" 0 cap3.md "
###### --- c1 ---
### 往復 1
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし

###### --- c2 ---
${h}
ありがとうございます。以下対応しました。
" "OK: 往復ブロック 1 個"
done

# --- 後置き文字列で上限超過をすり抜けない（往復4 C-1）------------------------
# 見出しを「数字で行が終端する」ものに限ると、`### 往復 4（最終）` のような後置きが
# 往復として数えられず、上限超過が黙って OK になる。これは停止条件が緑になる事故で、
# しかも `（最終）` は *上限に達した往復でこそ書かれる* ため、すり抜けと上限超過が
# 相関する。数字のあとに区切り文字を許して塞ぐ。
#
# 注意: 多バイト文字は文字クラス [—：（] ではなく選択 (—|：|（) で書く。mawk は
# バイト単位で扱うため、文字クラスに入れると継続バイトに誤一致する（`#{1,6}` と
# 同型の「mawk では黙って壊れる」系）。
for suffix in ' — 補足' '（最終）' ':' ' - x' '：まとめ' ' (最終)'; do
  run_case "NG: 後置き付き見出しでも上限超過を見逃さない [往復 4${suffix}]" 1 cap3.md "
###### --- c1 ---
### 往復 1
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし

###### --- c2 ---
### 往復 4${suffix}
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし
" "上限 3 を超えている"
done

# --- loop-extended ラベルによる上限超過の許容 --------------------------------
# 上限超過の扱いは「握り潰さず人間へ上げる」であって「常に禁止」ではない。承認された
# 延長と握り潰しを機械が区別できないため、no-spec と同じくラベルという明示的な操作を
# 要求し、例外を使った事実を記録に残す。**緩めるのは上限だけで、形式は緩めない。**
CAP_OVER='
###### --- c1 ---
### 往復 4
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし
'

run_case "NG: ラベルなしでは上限超過は落ちる" 1 cap3.md "$CAP_OVER" "上限 3 を超えている"

HAS_LOOP_EXTENDED=true \
  run_case "正常: loop-extended ラベルがあれば上限超過を通す" 0 cap3.md "$CAP_OVER" "OK（例外）"

HAS_LOOP_EXTENDED=true \
  run_case "正常: 例外で通すときも例外を使った事実を出力に残す" 0 cap3.md "$CAP_OVER" \
  "loop-extended ラベルによる人間承認済みの延長"

# ラベルは *上限だけ* を免除する。必須5行の欠落はラベルがあっても落ちる。
HAS_LOOP_EXTENDED=true \
  run_case "NG: ラベルがあっても形式（必須5行）は免除しない" 1 cap3.md '
###### --- c1 ---
### 往復 4
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
' "必須行が欠けている"

# `VAR=x func` の代入が関数終了後に残るかは bash のモード依存（POSIX モードでは残る）。
# 残ると以降のケースが黙ってラベル付きで走り、上限の回帰を捕まえられなくなる。
# 明示的に落としたうえで、落ちていることを次のケースで固定する。
unset HAS_LOOP_EXTENDED
run_case "NG: ラベル指定が後続ケースに漏れていない" 1 cap3.md "$CAP_OVER" "上限 3 を超えている"

# --- 行頭 # の非対称をなくす（I-1）------------------------------------------
# `###補足`（`#` 後に空白なし）もブロックを閉じる。閉じないと後続の `- 未解決` が
# 直前の往復に計上され、欠落を見逃す。往復見出し側が `###往復 4` を拾うのと同じ向き。
run_case "NG: 空白なし見出し（###補足）もブロックを閉じる" 1 cap3.md '
###### --- c1 ---
### 往復 1
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
###補足
- 未解決  : なし
' "必須行が欠けている" "未解決"

# --- ブロック0件 / 空入力 ---------------------------------------------------
run_case "NG: 空入力" 1 cap3.md '' "1つも無い"

run_case "NG: 往復ブロックが1つも無い" 1 cap3.md '
###### --- c1 ---
LGTM。特に指摘なし。
' "1つも無い"

# CI の失敗メッセージ（テンプレの N が数字でない）を貼っても誤爆しないこと。
run_case "NG: 失敗メッセージの貼り付けは往復として数えない" 1 cap3.md '
###### --- c1 ---
    ### 往復 N
    - Critical: <件数>
    - 未解決  : <次往復へ持ち越す点>
' "1つも無い"

# --- 上限の単一情報源への追随 -----------------------------------------------
# 上限はスクリプトにハードコードせず doc の表から読む（ADR 0010 §A）。
run_case "上限を変えた doc に追随する（4 ≤ 5 なら通る）" 0 cap5.md '
###### --- c1 ---
### 往復 4
- Critical: 0
- Warning : 0
- Info    : 0
- 対応    : x
- 未解決  : なし
' "最大 往復 4 ≤ 上限 5"

# 表の行に当たらなければ fail する。散文の太字数字を誤って拾わないこと
# （拾うと単一情報源を検査自身が壊す）。
run_case "NG: 上限を読み取れない doc では素通りさせない" 1 nocap.md "$OK_BLOCK" \
  "往復上限を" "読み取れなかった"

# --- 入力そのものが渡っていない場合 -----------------------------------------
echo "==> 入力欠落"
if out="$(TRAIL_FILE="" bash "$TARGET" 2>&1)"; then
  fail=$((fail + 1))
  echo "  FAIL TRAIL_FILE 未設定で成功してしまった"
else
  if grep -qF "TRAIL_FILE" <<< "$out"; then
    pass=$((pass + 1)); echo "  ok   TRAIL_FILE 未設定は失敗する"
  else
    fail=$((fail + 1)); echo "  FAIL TRAIL_FILE 未設定のメッセージが不適切: $out"
  fi
fi

if out="$(TRAIL_FILE="${WORK}/does-not-exist.txt" bash "$TARGET" 2>&1)"; then
  fail=$((fail + 1))
  echo "  FAIL 存在しない TRAIL_FILE で成功してしまった"
else
  pass=$((pass + 1)); echo "  ok   存在しない TRAIL_FILE は失敗する"
fi

echo ""
if [ "$fail" -ne 0 ]; then
  echo "  NG: $fail 件失敗 / $((pass + fail)) 件中（awk: $(awk -W version 2>&1 | head -n1)）"
  exit 1
fi
echo "  OK: $pass 件すべて通過（awk: $(awk -W version 2>&1 | head -n1)）"
